import { isDateTimePartiallyOrWithinDomain } from './is-datetime-partially-or-within-domain.js';
import { isTimeframe } from '../../core/components/annotations-timeseries/functions/is-timeframe.js';
import { TimeseriesAnnotationsTrackRendererProps } from '../context/TimeseriesChartAnnotationsConfig.context.js';
import { TimeseriesAnnotationsMarkerProps } from '../slots/annotations/Marker.js';

/**
 * Filters out annotations which are outside a provided time domain.
 * This must be done because the annotations' data can have a bigger domain than the Timeseries data, having annotations rendered out of bounds
 *
 * @param tracks -
 * @param domain -
 *
 * @returns tracks with filtered markers
 */
export function filterAnnotationsOutOfBounds(
  tracks: TimeseriesAnnotationsTrackRendererProps[],
  [domainStart, domainEnd]: number[],
): TimeseriesAnnotationsTrackRendererProps[] {
  return tracks.map((track: TimeseriesAnnotationsTrackRendererProps) => {
    const markersInBounds = track.markers.filter(
      (marker: TimeseriesAnnotationsMarkerProps) => {
        const { start } = marker.data;

        if (isTimeframe(marker.data)) {
          const { end } = marker.data;

          return isDateTimePartiallyOrWithinDomain(
            start,
            end,
            domainStart,
            domainEnd,
          );
        }

        return start.getTime() >= domainStart && start.getTime() <= domainEnd;
      },
    );

    return { ...track, markers: markersInBounds };
  });
}
